    }
}
void MergeSort(int mergeCp[], int head, int tail){
    if(head >= tail){
        return;
    }
    int middle = ((head + tail)/2);
    MergeSort(mergeCp,head, middle);
    MergeSort(mergeCp, middle + 1,tail);
    Merge(mergeCp, head, tail);
}

