            num++;
        }
    }
    int pivotI = head + num;
    int temp = quickCp[pivotI];
    quickCp[pivotI] = quickCp[head];
    quickCp[head] = temp;
    int i= head;
    int j = tail;
    while(i < pivotI && j > pivot){
