  int capacity;
  int size;

void maxHeapify(int index) {
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    int largest = index;
    if (left < size && heap[left] > heap[largest]) {
        largest = left;
    }
    if (right < size && heap[right] > heap[largest]) {
        largest = right;
    }
    if (largest != index) {
        int temp = heap[index];
        heap[index] = heap[largest];
        heap[largest] = temp;
        maxHeapify(largest);
    }
}

public:
    MaxHeap(int max_size) {
        capacity = max_size;
        heap = new int[capacity];
        size = 0;
    }
