struct DoubleNode {
  string data;
  DoubleNode *next;
  DoubleNode *prev;
};

DoubleNode *createNode(string &data);
DoubleNode *createNode(string &data) {
  DoubleNode *nn = new DoubleNode;
  nn->data = data;
  nn->next = NULL;
  nn->prev = NULL;
  return nn;
}

void insertNode(DoubleNode **head, string data);
void insertNode(DoubleNode **head, string data) {
  DoubleNode *nn = createNode(data);

  if (*head == NULL) {
    *head = nn;
  } else if (data < (*head)->data) {
    nn->next = *head;
    (*head)->prev = nn;
    *head = nn;
  } else {
      DoubleNode *curr = *head;
      while(curr->next != NULL && data > curr->next->data){
        curr = curr->next;
      }
      nn->next = curr->next;
      if (curr->next != NULL){
        curr->next->prev = nn;
      }
      curr->next =nn;
      nn->prev = curr;
  }
}

void deleteNode(DoubleNode **head, string nameToDelete);
void deleteNode(DoubleNode **head, string nameToDelete) {
    if(*head == NULL){
        return;
    }
    DoubleNode *curr = *head;
    while (curr != NULL){
        if(curr->data == nameToDelete){
            if(curr->prev != NULL){
                curr->prev->next = curr->next;
            }
            else {
                *head =curr->next;
            }
            if (curr->next != NULL){
                curr->next->prev = curr ->prev;
            }
            delete curr;
            return;
        }
        curr = curr->next;
    }
}

